-- ISOLATED QUALIFICATION ONLY. No production installation or asset ingestion.
begin;
create schema mip_markets;
revoke all on schema mip_markets from public;
alter table public.nodes add column private_candidate boolean not null default false;
alter table public.edges add column private_candidate boolean not null default false;
alter table public.nodes drop constraint nodes_type_check;
alter table public.nodes add constraint nodes_type_check check(type in
 ('event','actor','institution','document','anomaly','policy','topic','equity','cryptoasset','network'));
alter table public.nodes enable row level security;
alter table public.edges enable row level security;
create policy markets_private_nodes on public.nodes as restrictive for select to anon,authenticated using(not private_candidate);
create policy markets_private_edges on public.edges as restrictive for select to anon,authenticated
 using(not private_candidate and exists(select 1 from public.nodes n where n.id=source_id and not n.private_candidate) and exists(select 1 from public.nodes n where n.id=target_id and not n.private_candidate));
-- A privileged reader must explicitly filter; restrictive policies do not govern definer views.
-- Recreate the known aggregate independently of caller RLS.
create or replace view public.graph_coverage_public with(security_barrier=true,security_invoker=false) as
with article_totals as(select count(*)::integer article_count from public.articles where reader_state='eligible' and source_status='active'),
resolved_article_totals as(select count(distinct c.article_id)::integer articles_with_published_node from public.citations c join public.articles a on a.id=c.article_id and a.reader_state='eligible' and a.source_status='active'
 join public.nodes n on n.id=c.resolved_node_id and not n.private_candidate),
pending_graph_candidates as(select count(*)::integer pending_graph_candidate_count from public.cross_surface_candidates where candidate_type in('graph_node','graph_edge') and review_state in('pending','owner_hold')),
published_graph as(select
 (select count(*)::integer from public.nodes where not private_candidate) published_node_count,
 (select count(*)::integer from public.edges e join public.nodes s on s.id=e.source_id join public.nodes t on t.id=e.target_id where not e.private_candidate and not s.private_candidate and not t.private_candidate) documented_relationship_count)
select a.article_count,r.articles_with_published_node,greatest(a.article_count-r.articles_with_published_node,0)::integer articles_without_published_node,
 p.pending_graph_candidate_count,g.published_node_count,g.documented_relationship_count
from article_totals a cross join resolved_article_totals r cross join pending_graph_candidates p cross join published_graph g;
grant select on public.graph_coverage_public to anon,authenticated;

-- Fail closed for additional catalog-discoverable exposed graph views in this disposable target.
-- Dynamic SQL/functions and production surfaces still require a separate inventory.
do $inventory$
declare unknown_view text;
begin
 with recursive dependent(oid) as(
  select oid from pg_class where oid in('public.nodes'::regclass,'public.edges'::regclass)
  union
  select r.ev_class from dependent d join pg_depend p on p.refobjid=d.oid
   join pg_rewrite r on r.oid=p.objid where r.ev_class<>d.oid
 )
 select c.oid::regclass::text into unknown_view from dependent d join pg_class c on c.oid=d.oid
 where c.relkind in('v','m') and c.oid<>'public.graph_coverage_public'::regclass
 and(has_table_privilege('anon',c.oid,'SELECT') or has_table_privilege('authenticated',c.oid,'SELECT'))
 limit 1;
 if unknown_view is not null then raise exception 'mip_market_exposed_view_inventory_required';end if;
end $inventory$;

create function mip_markets.guard_private_graph() returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform 1 from mip_cutover_authority.publication_fence where id for update;
 if tg_op='UPDATE' and old.private_candidate and not new.private_candidate then raise exception 'mip_market_no_public_promotion';end if;
 if tg_table_name='nodes' then
  if new.type in('equity','cryptoasset','network') and not new.private_candidate then raise exception 'mip_market_private_required';end if;
 else
  if not new.private_candidate and exists(select 1 from public.nodes where id in(new.source_id,new.target_id) and private_candidate) then raise exception 'mip_market_private_endpoint';end if;
 end if;
 return new;
end $$;
create trigger markets_graph_guard before insert or update on public.nodes for each row execute function mip_markets.guard_private_graph();
create trigger markets_graph_guard before insert or update on public.edges for each row execute function mip_markets.guard_private_graph();
alter table evidence_pipeline.record_versions drop constraint record_versions_record_kind_check;
alter table evidence_pipeline.record_versions add constraint record_versions_record_kind_check check(record_kind in('article','graph_node','temporal_assessment','graph_edge'));
create trigger mip_edge_version after insert or update or delete on public.edges for each row execute function evidence_pipeline.capture_version('graph_edge');
alter table evidence_pipeline.evidence_candidates drop constraint evidence_candidates_candidate_kind_check;
alter table evidence_pipeline.evidence_candidates add constraint evidence_candidates_candidate_kind_check check(candidate_kind in('claim','graph_relationship','timeline','geography','typed_graph_relationship'));
alter table evidence_pipeline.evidence_candidates
 add column typed_edge_id uuid references public.edges(id),
 add column subject_version_id uuid references evidence_pipeline.record_versions(id),
 add column object_version_id uuid references evidence_pipeline.record_versions(id),
 add column edge_version_id uuid references evidence_pipeline.record_versions(id),
 add column identity_version_id uuid references evidence_pipeline.record_versions(id),
 add column relationship_kind text,
 add column valid_from timestamptz,
 add column valid_to timestamptz;
alter table evidence_pipeline.evidence_candidates add constraint typed_candidate_shape check(
 (candidate_kind='typed_graph_relationship' and typed_edge_id is not null and subject_version_id is not null and object_version_id is not null and edge_version_id is not null
 and relationship_kind in('direct_reporting','ownership','operation','supply','regulation','financing','protocol_dependency')
 and valid_from is not null and isfinite(valid_from) and (valid_to is null or(isfinite(valid_to) and valid_to>valid_from))
 and event_node_id is null and related_node_id is null and place_id is null and spatial_revision_id is null)
 or(candidate_kind<>'typed_graph_relationship' and typed_edge_id is null and subject_version_id is null and object_version_id is null and edge_version_id is null and identity_version_id is null and relationship_kind is null and valid_from is null and valid_to is null));
create index market_candidate_edge on evidence_pipeline.evidence_candidates(typed_edge_id);
create index market_candidate_subject_version on evidence_pipeline.evidence_candidates(subject_version_id);
create index market_candidate_object_version on evidence_pipeline.evidence_candidates(object_version_id);
create index market_candidate_identity_version on evidence_pipeline.evidence_candidates(identity_version_id);
create index market_candidate_edge_version on evidence_pipeline.evidence_candidates(edge_version_id);
create function mip_markets.guard_candidate() returns trigger language plpgsql set search_path='' as $$
declare s evidence_pipeline.record_versions;o evidence_pipeline.record_versions;e evidence_pipeline.record_versions;c evidence_pipeline.article_captures;
 edge public.edges;identity_record evidence_pipeline.record_versions;expected_identity text;
begin
 if new.candidate_kind<>'typed_graph_relationship' then return new;end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 select * into strict edge from public.edges where id=new.typed_edge_id;
 select * into strict s from evidence_pipeline.record_versions where id=new.subject_version_id;
 select * into strict o from evidence_pipeline.record_versions where id=new.object_version_id;
 select * into strict e from evidence_pipeline.record_versions where id=new.edge_version_id;
 if s.record_kind<>'graph_node' or o.record_kind<>'graph_node' or e.record_kind<>'graph_edge'
 or s.record_key<>edge.source_id::text or o.record_key<>edge.target_id::text or e.record_key<>edge.id::text
 or e.payload->>'source_id'<>s.record_key or e.payload->>'target_id'<>o.record_key
 or e.payload->>'type' is distinct from new.relationship_kind
 or not edge.private_candidate or edge.type<>new.relationship_kind
 or e.operation='delete' or s.operation='delete' or o.operation='delete'
 then raise exception 'mip_market_exact_endpoint_binding';end if;
 if exists(select 1 from evidence_pipeline.record_versions v where (v.record_kind,v.record_key) in((s.record_kind,s.record_key),(o.record_kind,o.record_key),(e.record_kind,e.record_key))
 and v.ordinal>case when v.record_kind=e.record_kind and v.record_key=e.record_key then e.ordinal when v.record_key=s.record_key then s.ordinal else o.ordinal end)
 then raise exception 'mip_market_stale_identity';end if;
 if s.payload->>'type' in('equity','cryptoasset') then
  expected_identity:=case when s.payload->>'type'='equity' then s.payload#>>'{metadata,issuer_version_id}' else s.payload#>>'{metadata,network_version_id}' end;
  if new.identity_version_id is null or new.identity_version_id::text is distinct from expected_identity then raise exception 'mip_market_companion_version_required';end if;
  select * into strict identity_record from evidence_pipeline.record_versions where id=new.identity_version_id;
  if identity_record.record_kind<>'graph_node' or identity_record.operation='delete'
   or identity_record.record_key is distinct from (case when s.payload->>'type'='equity' then s.payload#>>'{metadata,issuer_id}' else s.payload#>>'{metadata,network_id}' end)
   or(case when s.payload->>'type'='equity' then identity_record.payload->>'type' not in('actor','institution') else identity_record.payload->>'type'<>'network' end)
   or exists(select 1 from evidence_pipeline.record_versions v where v.record_kind='graph_node' and v.record_key=identity_record.record_key and v.ordinal>identity_record.ordinal)
   then raise exception 'mip_market_companion_binding';end if;
 elsif new.identity_version_id is not null then raise exception 'mip_market_unexpected_companion';end if;
 select * into strict c from evidence_pipeline.article_captures where id=new.capture_id;
 if new.span_end>char_length(c.payload->>new.source_field) or substring(c.payload->>new.source_field from new.span_start+1 for new.span_end-new.span_start) is distinct from new.excerpt then raise exception 'mip_market_exact_span';end if;
 return new;
end $$;
create trigger market_candidate_binding before insert on evidence_pipeline.evidence_candidates for each row execute function mip_markets.guard_candidate();
alter function evidence_pipeline.assessment_context(uuid,uuid[],bigint[]) rename to assessment_context_before_markets;
create function evidence_pipeline.assessment_context(p_candidate uuid,p_parents uuid[] default '{}',p_extra bigint[] default '{}') returns jsonb language plpgsql set search_path='' as $$
declare c evidence_pipeline.evidence_candidates;positions bigint[];
begin
 select * into strict c from evidence_pipeline.evidence_candidates where id=p_candidate;
 if c.candidate_kind='typed_graph_relationship' then
  select array_agg(position order by position) into positions from evidence_pipeline.evidence_changes where record_version_id in(c.subject_version_id,c.object_version_id,c.edge_version_id,c.identity_version_id);
  if cardinality(positions)<>(select count(distinct x) from unnest(array[c.subject_version_id,c.object_version_id,c.edge_version_id,c.identity_version_id])x where x is not null) then raise exception 'mip_market_missing_retained_change';end if;
  select array_agg(distinct x order by x) into p_extra from unnest(p_extra||positions)x;
 end if;
 return evidence_pipeline.assessment_context_before_markets(p_candidate,p_parents,p_extra);
end $$;
revoke all on function evidence_pipeline.assessment_context(uuid,uuid[],bigint[]) from public,anon,authenticated;
grant execute on function evidence_pipeline.assessment_context(uuid,uuid[],bigint[]) to service_role;
revoke all on all functions in schema mip_markets from public,anon,authenticated,service_role;
commit;

-- Private, execute-only retained Markets reader. No public publication adapter.
begin;
grant usage on schema mip_markets to mip_hypothesis_owner,mip_hypothesis_gateway;
grant select on evidence_pipeline.evidence_candidates,evidence_pipeline.assessments,evidence_pipeline.record_versions,evidence_pipeline.article_captures,
 public.nodes,public.edges to mip_hypothesis_owner;
create policy market_nodes_reader on public.nodes for select to mip_hypothesis_owner using(true);
create policy market_edges_reader on public.edges for select to mip_hypothesis_owner using(true);
create policy market_candidates_reader on evidence_pipeline.evidence_candidates for select to mip_hypothesis_owner using(true);
create policy market_assessments_reader on evidence_pipeline.assessments for select to mip_hypothesis_owner using(true);
create policy market_versions_reader on evidence_pipeline.record_versions for select to mip_hypothesis_owner using(true);
create policy market_captures_reader on evidence_pipeline.article_captures for select to mip_hypothesis_owner using(true);
grant execute on function evidence_pipeline.read_assessment(uuid,timestamptz),evidence_pipeline.assessment_causes(uuid) to mip_hypothesis_owner;
grant select on evidence_pipeline.change_subjects,evidence_pipeline.evidence_changes to mip_hypothesis_owner;
create policy market_changes_reader on evidence_pipeline.evidence_changes for select to mip_hypothesis_owner using(true);
create function mip_markets.read_private(p_user uuid,p_investigation uuid,p_version uuid,p_source text,p_asset uuid,p_event uuid,p_at timestamptz) returns jsonb
language plpgsql security definer set search_path='' as $$
declare binding jsonb;path record;c evidence_pipeline.evidence_candidates;a jsonb;cap evidence_pipeline.article_captures;
 v evidence_pipeline.record_versions;material uuid;input jsonb;input_position text;op text;domain text;checked jsonb;
 asset jsonb;asset_version uuid;asset_companion jsonb;subject_node jsonb;object_node jsonb;companion evidence_pipeline.record_versions;aliases jsonb:='[]';alias_item jsonb;paths jsonb:='[]';hops jsonb;support jsonb;cid uuid;retained_ids uuid[];candidate_ids uuid[];scoped_ids uuid[];
begin
 if p_asset is null and p_event is null or p_at is null or not isfinite(p_at) then raise exception 'mip_market_bounded_identity_required';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 binding:=mip_hypothesis.observation_binding(p_user,p_investigation,p_version);
 if p_source is null or btrim(p_source)='' or p_source='cc-definition-batch-v1' then raise exception 'mip_market_source_denied';end if;
 select array_agg(coalesce(value->'capture'->>'id',value->'record_version'->>'id')::uuid) into retained_ids
 from jsonb_array_elements(binding->'observation'->'snapshot'->'inputs');
 if (p_asset is not null and not exists(select 1 from evidence_pipeline.record_versions where id=any(retained_ids) and record_kind='graph_node' and record_key=p_asset::text and payload->>'type' in('equity','cryptoasset')))
 or(p_event is not null and not exists(select 1 from evidence_pipeline.record_versions where id=any(retained_ids) and record_kind='graph_node' and record_key=p_event::text and payload->>'type'='event'))
 then raise exception 'mip_market_identity_not_in_workspace';end if;
 select scope_candidate_ids into strict scoped_ids from evidence_pipeline.investigation_observations where id=(binding->'observation'->>'id')::uuid;
 select coalesce(array_agg(id order by id),'{}') into candidate_ids from(
  select cand.id from evidence_pipeline.evidence_candidates cand
  where cand.id=any(scoped_ids) and cand.candidate_kind='typed_graph_relationship' and cand.capture_id=any(retained_ids)
   and cand.subject_version_id=any(retained_ids) and cand.object_version_id=any(retained_ids) and cand.edge_version_id=any(retained_ids)
   and(cand.identity_version_id is null or cand.identity_version_id=any(retained_ids))
   and cand.valid_from<=p_at and(cand.valid_to is null or p_at<cand.valid_to)
  order by cand.id limit 17
 ) bounded;
 if cardinality(candidate_ids)>16 then raise exception 'mip_market_candidate_budget';end if;
 -- Recursion sees at most sixteen explicitly retained candidates, not global private history.
 -- A simple directed path is uniquely ordered by its edge subset: at most 2^16 subsets.
 -- Same shared edge identities in both discovery directions. No alternate graph.
 for path in with recursive eligible as(
  select cand.id,e.source_id,e.target_id,cand.subject_version_id,cand.object_version_id from evidence_pipeline.evidence_candidates cand join public.edges e on e.id=cand.typed_edge_id
  where cand.id=any(candidate_ids)
 ), walk as(
  select n.id asset_id,e.target_id endpoint,e.object_version_id endpoint_version,array[n.id,e.target_id] nodes,array[e.id] candidates
  from public.nodes n join eligible e on e.source_id=n.id
  where n.type in('equity','cryptoasset') and(p_asset is null or n.id=p_asset)
  union all
  select w.asset_id,e.target_id,e.object_version_id,w.nodes||e.target_id,w.candidates||e.id from walk w join eligible e on e.source_id=w.endpoint and e.subject_version_id=w.endpoint_version
  where cardinality(w.candidates)<8 and not e.target_id=any(w.nodes)
 ) select w.* from walk w join public.nodes n on n.id=w.endpoint and n.type='event'
 where(p_event is null or w.endpoint=p_event) order by w.asset_id,w.endpoint,w.candidates limit 33
 loop
  if jsonb_array_length(paths)>=32 then raise exception 'mip_market_path_budget';end if;
  hops:='[]';asset:=null;
  foreach cid in array path.candidates loop
   select * into strict c from evidence_pipeline.evidence_candidates where id=cid;
   select evidence_pipeline.read_assessment(x.id) into a from evidence_pipeline.assessments x
   where x.candidate_id=c.id and not exists(select 1 from evidence_pipeline.assessments y where y.predecessor_id=x.id)
   order by x.ordinal desc limit 1;
   if a is null or a->>'outcome'<>'supported' or a->'stale'<>'false'::jsonb or jsonb_array_length(a->'superseded_by')<>0 then raise exception 'mip_market_assessment_unavailable';end if;
   -- Every retained object must already belong to this exact workspace observation.
   -- Sorted UUID iteration provides deterministic material lock/check order.
   for material in select x from unnest(array[c.subject_version_id,c.object_version_id,c.edge_version_id,c.capture_id,c.identity_version_id])x where x is not null order by x loop
    select value into input from jsonb_array_elements(binding->'observation'->'snapshot'->'inputs')
     where coalesce(value->'capture'->>'id',value->'record_version'->>'id')=material::text;
    if input is null then raise exception 'mip_market_material_not_in_workspace';end if;
    input_position:=input->>'position';
    foreach op in array array['retention','analysis','excerpt_display'] loop foreach domain in array array['rights','privacy'] loop
     checked:=mip_hypothesis.operation_permission(p_user,p_investigation,p_version,input_position,p_source,op,domain);
     if checked->'allowed' is distinct from 'true'::jsonb then raise exception using errcode='42501',message='mip_market_operation_denied';end if;
    end loop;end loop;
   end loop;
   select * into strict v from evidence_pipeline.record_versions where id=c.subject_version_id;
   if v.record_key=path.asset_id::text then
    asset:=v.payload;asset_version:=v.id;
    select * into strict companion from evidence_pipeline.record_versions where id=c.identity_version_id;
    if asset->>'type'='equity' then
     if companion.record_key is distinct from asset#>>'{metadata,issuer_id}' or companion.payload->>'type' not in('actor','institution') then raise exception 'mip_market_issuer_required';end if;
    elsif asset->>'type'='cryptoasset' then
     if companion.record_key is distinct from asset#>>'{metadata,network_id}' or companion.payload->>'type'<>'network'
      or nullif(btrim(asset#>>'{metadata,asset_identifier}'),'') is null then raise exception 'mip_market_network_required';end if;
    else raise exception 'mip_market_asset_type';end if;
    asset_companion:=jsonb_build_object('id',companion.record_key,'version_id',companion.id,'type',companion.payload->>'type','name',companion.payload->>'label');
    if asset#>>'{metadata,valid_from}' is null or not isfinite((asset#>>'{metadata,valid_from}')::timestamptz)
     or p_at<(asset#>>'{metadata,valid_from}')::timestamptz or(asset#>>'{metadata,valid_to}' is not null and
     (not isfinite((asset#>>'{metadata,valid_to}')::timestamptz) or p_at>=(asset#>>'{metadata,valid_to}')::timestamptz))
     then raise exception 'mip_market_identity_not_valid';end if;
    if jsonb_typeof(asset#>'{metadata,aliases}') is distinct from 'array' or jsonb_array_length(asset#>'{metadata,aliases}')>32 then raise exception 'mip_market_aliases_required';end if;
    aliases:='[]';
    for alias_item in select value from jsonb_array_elements(asset#>'{metadata,aliases}') loop
     if nullif(btrim(alias_item->>'symbol'),'') is null or nullif(btrim(alias_item->>'namespace'),'') is null or alias_item->>'valid_from' is null
      or not isfinite((alias_item->>'valid_from')::timestamptz) or(alias_item->>'valid_to' is not null and((alias_item->>'valid_to')::timestamptz<=(alias_item->>'valid_from')::timestamptz or not isfinite((alias_item->>'valid_to')::timestamptz))) then raise exception 'mip_market_alias_invalid';end if;
     if(alias_item->>'valid_from')::timestamptz<=p_at and(alias_item->>'valid_to' is null or p_at<(alias_item->>'valid_to')::timestamptz) then
      aliases:=aliases||jsonb_build_array(jsonb_build_object('symbol',alias_item->>'symbol','namespace',alias_item->>'namespace','valid_from',alias_item->>'valid_from','valid_to',alias_item->>'valid_to'));
     end if;
    end loop;
   end if;
   select * into strict cap from evidence_pipeline.article_captures where id=c.capture_id;
   select value->>'position' into input_position from jsonb_array_elements(binding->'observation'->'snapshot'->'inputs') where value->'capture'->>'id'=cap.id::text;
   support:=mip_hypothesis.retained_excerpt(p_user,p_investigation,p_version,input_position,p_source,c.source_field,c.span_start,c.span_end,encode(sha256(convert_to(c.excerpt,'UTF8')),'hex'));
   select jsonb_build_object('id',record_key,'version_id',id,'type',payload->>'type','name',payload->>'label') into subject_node from evidence_pipeline.record_versions where id=c.subject_version_id;
   select jsonb_build_object('id',record_key,'version_id',id,'type',payload->>'type','name',payload->>'label') into object_node from evidence_pipeline.record_versions where id=c.object_version_id;
   hops:=hops||jsonb_build_array(jsonb_build_object('edge_id',c.typed_edge_id,'edge_version_id',c.edge_version_id,
    'subject',subject_node,'object',object_node,'subject_version_id',c.subject_version_id,'object_version_id',c.object_version_id,'candidate_id',c.id,'assessment_id',a->>'id',
    'relationship',c.relationship_kind,'valid_from',c.valid_from,'valid_to',c.valid_to,'uncertainty',a->>'remaining_uncertainty',
    'capture_id',cap.id,'article_id',cap.article_id,'captured_at',cap.captured_at,'published_at',cap.payload->'published_at','source_url',cap.payload->'url','capture_payload_hash',cap.content_hash,'support',support));
  end loop;
  if asset is null then raise exception 'mip_market_asset_unavailable';end if;
  paths:=paths||jsonb_build_array(jsonb_build_object('asset_id',path.asset_id,'asset_version_id',asset_version,'asset_kind',asset->>'type','name',asset->>'label',
   'identity_companion',asset_companion,'asset_identifier',asset#>>'{metadata,asset_identifier}','valid_from',asset#>>'{metadata,valid_from}','valid_to',asset#>>'{metadata,valid_to}','aliases_version_id',asset_version,'aliases',aliases,'event_id',path.endpoint,'hops',hops,'relation',case when jsonb_array_length(hops)=1 and hops->0->>'relationship'='direct_reporting' then 'direct_reporting' else 'connected_development' end));
 end loop;
 return jsonb_build_object('contract_version','mip_markets_private_qualification_v1','investigation_id',p_investigation,'workspace_version_id',p_version,
 'observation_id',binding->'observation'->>'id','asset_id',p_asset,'event_id',p_event,'at',p_at,'paths',paths,'publication_allowed',false,'historical_time_qualified',false,'broader_context',jsonb_build_array(),
 'coverage','bounded_explicit_typed_paths_only','source_root_lineage_qualified',false);
end $$;
alter function mip_markets.read_private(uuid,uuid,uuid,text,uuid,uuid,timestamptz) owner to mip_hypothesis_owner;
revoke all on function mip_markets.read_private(uuid,uuid,uuid,text,uuid,uuid,timestamptz) from public,anon,authenticated,service_role;
grant execute on function mip_markets.read_private(uuid,uuid,uuid,text,uuid,uuid,timestamptz) to mip_hypothesis_gateway;
commit;

import {marketInstant} from '../../functions/_shared/marketsEvidenceContract.mjs'
// Trusted server seam only; no default endpoint/identity, browser credentials or publication.
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
export function createPrivateMarketsReader({authenticate,sourceProject,query}={}){
 if(typeof authenticate!=='function'||typeof query!=='function'||typeof sourceProject!=='string'||!sourceProject.trim()||sourceProject==='cc-definition-batch-v1')throw Error('mip_markets_unconfigured')
 const source=sourceProject
 return Object.freeze({read:async(request,input)=>{
  try{
