-- No head/method write grants to reviewer, gateway, broker or worker.
create trigger a_identity_fence before insert or update or delete or truncate on mip_hypothesis.method_heads
 for each statement execute function mip_identity.serialize_change();
create trigger b_publication_fence before insert or update or delete or truncate on mip_hypothesis.method_heads
 for each statement execute function mip_hypothesis.source_change_fence();
create trigger c_no_revision_reuse before insert or update or delete on mip_hypothesis.method_heads
 for each row execute function mip_identity.guard_revision_reuse();

create trigger hypothesis_generation_permission after insert or update or delete on mip_identity.operation_evidence_heads
 for each row execute function mip_hypothesis.generation_permission_change();

-- Read-only operational ledger for the isolated generation data plane. No lease/token/source text.
set role mip_hypothesis_owner;
create function mip_hypothesis.generation_backlog(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare entries jsonb;
begin
 -- Current private investigation membership, independently of any worker lease.
 perform mip_hypothesis.read_bound_history(p_user,p_investigation);
 select coalesce(jsonb_agg(jsonb_build_object('generation_id',g.id,'request_id',g.request_id,'workspace_version_id',g.workspace_version_id,
  'observation_id',g.observation_id,'predecessor_id',g.predecessor_id,'input_hash',g.input_hash,
  'method_revision',g.method_revision,'implementation',g.implementation,'state',j.state,'recorded_at',to_char(g.recorded_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'lease_expired',j.state='processing' and j.lease_expires_at<=clock_timestamp(),
  'retained_for_reconciliation',j.state in('processing','failed') or b.generation_id is not null,
  'block_reason',b.reason,'completed_revision_id',o.assessment_revision_id)
  order by g.recorded_at,g.id),'[]'::jsonb) into entries
 from mip_hypothesis.generations g join mip_hypothesis.generation_jobs j on j.generation_id=g.id
 left join mip_hypothesis.generation_blocks b on b.generation_id=g.id
 left join mip_hypothesis.generation_outputs o on o.generation_id=g.id
 where g.investigation_id=p_investigation;
 return jsonb_build_object('contract_version','mip_hypothesis_generation_backlog_v1','investigation_id',p_investigation,
  'entries',entries,'coverage','retained_generation_jobs','current_authority_qualified',false,
  'automatic_retry',false,'force_cancellation',false,'publication_allowed',false);
end $$;
revoke all on function mip_hypothesis.generation_backlog(uuid,uuid) from public;
grant execute on function mip_hypothesis.generation_backlog(uuid,uuid) to mip_hypothesis_gateway;
reset role;

-- Isolated authoritative method-head change signals. No method/policy approval or deployment.
set role mip_hypothesis_owner;
alter table mip_hypothesis.reassessment_causes drop constraint reassessment_causes_kind_check;
alter table mip_hypothesis.reassessment_causes add constraint reassessment_causes_kind_check
 check(kind in('retained_source_change','retained_assessment_change','workspace_changed','permission_changed','human_reconsideration','method_changed'));

alter function mip_hypothesis.discover_reassessment_causes(uuid) rename to discover_reassessment_causes_pre_method;
create function mip_hypothesis.discover_reassessment_causes(p_investigation uuid) returns void
language plpgsql security definer set search_path='' as $$
declare g mip_hypothesis.generations; rid uuid; observed uuid; enabled boolean; key text;
begin
 -- Existing discovery acquires publication fence then question lock. A method
 -- mutation obtains identity/publication fences before changing the head.
 perform mip_hypothesis.discover_reassessment_causes_pre_method(p_investigation);
 select id into rid from mip_hypothesis.revisions where investigation_id=p_investigation order by revision desc limit 1;
 select gen.* into g from mip_hypothesis.generations gen
  join mip_hypothesis.generation_outputs o on o.generation_id=gen.id where o.assessment_revision_id=rid;
 if not found then return;end if;
 select revision,active into observed,enabled from mip_hypothesis.method_heads where implementation=g.implementation;
 if observed is not distinct from g.method_revision and enabled is true then return;end if;
 key:='method:'||g.method_revision::text||':'||coalesce(observed::text,'missing')||':'||coalesce(enabled::text,'missing');
 insert into mip_hypothesis.reassessment_causes(investigation_id,revision_id,cause_key,kind,related_version_id,detail)
 values(p_investigation,rid,key,'method_changed',observed,jsonb_build_object(
  'implementation',g.implementation,'accepted_method_revision',g.method_revision,
  'observed_method_revision',observed,'observed_active',coalesce(enabled,false),
  'classification','method_change_requires_reassessment_not_approval'))
 on conflict(revision_id,cause_key) do nothing;
end $$;

create function mip_hypothesis.method_change_reassessment() returns trigger
language plpgsql security definer set search_path='' as $$
declare iid uuid;
begin
 -- Latest generated revisions only; manual authoring is not falsely attributed
 -- to an evaluated method. Deterministic question order for multi-row changes.
 for iid in select distinct g.investigation_id from mip_hypothesis.generations g
  join mip_hypothesis.generation_outputs o on o.generation_id=g.id
  where not exists(select 1 from mip_hypothesis.revisions r
   join mip_hypothesis.revisions prior on prior.id=o.assessment_revision_id
   where r.investigation_id=g.investigation_id and r.revision>prior.revision)
  order by g.investigation_id
 loop perform mip_hypothesis.discover_reassessment_causes(iid);end loop;
 return null;
end $$;
revoke all on function mip_hypothesis.discover_reassessment_causes_pre_method(uuid),
 mip_hypothesis.discover_reassessment_causes(uuid),mip_hypothesis.method_change_reassessment() from public;
reset role;
-- Statement trigger covers removal of all heads too. Existing BEFORE fences
-- serialize this cause insertion with completion; rollback rolls both back.
create trigger hypothesis_method_reassessment after insert or update or delete or truncate
 on mip_hypothesis.method_heads for each statement execute function mip_hypothesis.method_change_reassessment();

-- Explicit fresh-generation recovery. Isolated only; no scheduler, cancellation or production grants.
set role mip_hypothesis_owner;
create table mip_hypothesis.generation_recoveries(
 request_id uuid primary key, prior_generation_id uuid not null unique references mip_hypothesis.generations,
 generation_id uuid not null unique references mip_hypothesis.generations,
 author_id uuid not null, arguments jsonb not null, receipt jsonb not null,
 recorded_at timestamptz not null default clock_timestamp(),
 check(prior_generation_id<>generation_id)
);
alter table mip_hypothesis.generation_recoveries enable row level security;
alter table mip_hypothesis.generation_recoveries force row level security;
create policy owner_only on mip_hypothesis.generation_recoveries to mip_hypothesis_owner using(true) with check(true);
create trigger immutable_rows before update or delete on mip_hypothesis.generation_recoveries
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.generation_recoveries
 for each statement execute function mip_hypothesis.reject_mutation();

create function mip_hypothesis.recover_generation(p_user uuid,p_investigation uuid,p_version uuid,p_source_project text,
 p_request uuid,p_runtime text,p_method uuid,p_prior uuid,p_spec jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare prior mip_hypothesis.generations; job mip_hypothesis.generation_jobs; old mip_hypothesis.generation_recoveries;
 method mip_hypothesis.method_versions; args jsonb; result jsonb; b jsonb;
begin
 select * into strict method from mip_hypothesis.method_versions where revision=p_method;
 perform mip_hypothesis.generation_authority(p_runtime,p_source_project,method.implementation,p_method);
 -- Same runtime/job serialization as completion. If completion commits first,
 -- it is observed here; an outstanding processing row is never cancelled.
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-worker:'||p_runtime,0));
 select * into prior from mip_hypothesis.generations where id=p_prior;
 if not found or prior.author_id is distinct from p_user or prior.investigation_id is distinct from p_investigation
  or prior.runtime is distinct from p_runtime or prior.source_project is distinct from p_source_project then
  raise exception 'mip_hypothesis_recovery_owner_scope';end if;
 select * into strict job from mip_hypothesis.generation_jobs where generation_id=p_prior for update;
 args:=jsonb_build_object('user',p_user,'investigation',p_investigation,'version',p_version,'source',p_source_project,
  'runtime',p_runtime,'method',p_method,'prior',p_prior,'spec',p_spec);
 -- Retaining old input references does not waive their current permission.
 for b in select value from jsonb_array_elements(prior.closure_bindings) loop
  perform mip_hypothesis.require_observed_operations(p_user,p_investigation,(b->>'workspace_version_id')::uuid,
   p_source_project,b->>'input_position');
 end loop;
 select * into old from mip_hypothesis.generation_recoveries where request_id=p_request or prior_generation_id=p_prior;
 if found then
  if old.request_id is distinct from p_request or old.arguments is distinct from args then
   raise exception 'mip_hypothesis_recovery_conflict';end if;
  -- Reuse capture's current authority, exact arguments and completed-result recovery.
  perform mip_hypothesis.capture_generation(p_user,p_investigation,p_version,p_source_project,p_request,p_runtime,p_method,p_spec);
  return old.receipt;
 end if;
 if not(job.state='failed' or (job.state='processing' and job.lease_expires_at is not null and job.lease_expires_at<=clock_timestamp())) then
  raise exception 'mip_hypothesis_recovery_not_stranded';end if;
 -- Prevent attaching a pre-existing ordinary capture to this recovery request.
 if exists(select 1 from mip_hypothesis.generations where request_id=p_request) then
  raise exception 'mip_hypothesis_recovery_conflict';end if;
 result:=mip_hypothesis.capture_generation(p_user,p_investigation,p_version,p_source_project,p_request,p_runtime,p_method,p_spec);
 result:=result||jsonb_build_object('prior_generation_id',p_prior,'prior_state',job.state,
  'prior_retained',true,'force_cancellation',false,'automatic_retry',false);
 insert into mip_hypothesis.generation_recoveries(request_id,prior_generation_id,generation_id,author_id,arguments,receipt)
 values(p_request,p_prior,(result->>'generation_id')::uuid,p_user,args,result);
 return result;
end $$;
revoke all on mip_hypothesis.generation_recoveries from public;
revoke all on function mip_hypothesis.recover_generation(uuid,uuid,uuid,text,uuid,text,uuid,uuid,jsonb) from public;
grant execute on function mip_hypothesis.recover_generation(uuid,uuid,uuid,text,uuid,text,uuid,uuid,jsonb) to mip_hypothesis_gateway;
reset role;

-- Read-only recovery lineage over retained generations. Isolated; no new production grants.
set role mip_hypothesis_owner;
alter function mip_hypothesis.generation_backlog(uuid,uuid) rename to generation_backlog_pre_recovery;
revoke execute on function mip_hypothesis.generation_backlog_pre_recovery(uuid,uuid) from mip_hypothesis_gateway;
create function mip_hypothesis.generation_backlog(p_user uuid,p_investigation uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare result jsonb; entries jsonb;
begin
 result:=mip_hypothesis.generation_backlog_pre_recovery(p_user,p_investigation);
 -- The original reader holds current private membership. Only generation IDs
 -- from that same investigation are exposed, never request arguments or secrets.
 select coalesce(jsonb_agg(e.value||jsonb_build_object(
  'recovery_prior_generation_id',prior.prior_generation_id,
  'recovery_generation_id',next.generation_id) order by e.ordinality),'[]'::jsonb)
 into entries from jsonb_array_elements(result->'entries') with ordinality e(value,ordinality)
 left join mip_hypothesis.generation_recoveries prior on prior.generation_id=(e.value->>'generation_id')::uuid
 left join mip_hypothesis.generation_recoveries next on next.prior_generation_id=(e.value->>'generation_id')::uuid;
 return result||jsonb_build_object('contract_version','mip_hypothesis_generation_backlog_v2','entries',entries);
end $$;
revoke all on function mip_hypothesis.generation_backlog(uuid,uuid) from public;
grant execute on function mip_hypothesis.generation_backlog(uuid,uuid) to mip_hypothesis_gateway;
reset role;

-- Isolated exact-version acknowledgement, not factual approval or publication.
-- Extends existing workspace receipt/CAS semantics; no live route or role is provisioned.
set role mip_hypothesis_owner;
create table mip_hypothesis.review_acknowledgements(
 investigation_id uuid not null,
 request_id uuid not null,
 reviewer_id uuid not null,
 revision_id uuid not null,
 revision bigint not null check(revision>0),
 receipt_sequence bigint not null check(receipt_sequence>0),
 previous_receipt_id uuid,
 receipt jsonb not null,
 recorded_at timestamptz not null default clock_timestamp(),
 primary key(investigation_id,request_id),
 unique(investigation_id,reviewer_id,request_id),
 unique(investigation_id,reviewer_id,receipt_sequence),
 unique(investigation_id,reviewer_id,revision_id),
 foreign key(investigation_id,revision_id) references mip_hypothesis.revisions(investigation_id,id),
 foreign key(investigation_id,reviewer_id,previous_receipt_id)
  references mip_hypothesis.review_acknowledgements(investigation_id,reviewer_id,request_id),
 check(receipt->>'is_approval' is not distinct from 'false'),
 check(receipt->>'publication_allowed' is not distinct from 'false'),
 check(receipt->>'resolves_reassessment' is not distinct from 'false')
);
alter table mip_hypothesis.review_acknowledgements enable row level security;
alter table mip_hypothesis.review_acknowledgements force row level security;
create policy owner_only on mip_hypothesis.review_acknowledgements to mip_hypothesis_owner using(true) with check(true);
create trigger immutable_rows before update or delete on mip_hypothesis.review_acknowledgements
 for each row execute function mip_hypothesis.reject_mutation();
create trigger immutable_table before truncate on mip_hypothesis.review_acknowledgements
 for each statement execute function mip_hypothesis.reject_mutation();

create function mip_hypothesis.acknowledge_review(p_user uuid,p_investigation uuid,p_request uuid,p_revision uuid,p_previous uuid)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare history jsonb; item jsonb; access text; prior mip_hypothesis.review_acknowledgements;
 existing mip_hypothesis.review_acknowledgements; result jsonb; seq bigint; target_revision bigint; recorded timestamptz;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 if p_user is null or p_investigation is null or p_request is null or p_revision is null then
  raise exception using errcode='22023',message='missing review acknowledgement identity';end if;
 -- Current permission reader obtains publication then membership fences, including on retries.
 history:=mip_hypothesis.read_bound_history(p_user,p_investigation);
 select access_role into access from evidence_pipeline.investigation_memberships
  where investigation_id=p_investigation and user_id=p_user;
 if access is distinct from 'reviewer' then raise exception using errcode='42501',message='hypothesis acknowledgement denied';end if;
 perform pg_advisory_xact_lock(hashtextextended('mip-hypothesis-question:'||p_investigation::text,0));
 -- A wait may cross a permission expiry even while mutation fences remain held.
 history:=mip_hypothesis.read_bound_history(p_user,p_investigation);
 select value into item from jsonb_array_elements(history->'entries') where value->>'revision_id'=p_revision::text;
 if not found or item->>'status' is distinct from 'available' then
  raise exception using errcode='42501',message='review target unavailable under current permissions';end if;
 target_revision:=(item->>'revision')::bigint;
 select * into existing from mip_hypothesis.review_acknowledgements
  where investigation_id=p_investigation and request_id=p_request;
 if found then
  if existing.reviewer_id<>p_user or existing.revision_id<>p_revision or existing.previous_receipt_id is distinct from p_previous then
   raise exception using errcode='23505',message='review acknowledgement retry conflict';end if;
  return existing.receipt;
 end if;
 select * into prior from mip_hypothesis.review_acknowledgements
  where investigation_id=p_investigation and reviewer_id=p_user order by receipt_sequence desc limit 1;
 if prior.request_id is distinct from p_previous then
  raise exception using errcode='40001',message='review acknowledgement predecessor changed';end if;
 if prior.revision is not null and target_revision<=prior.revision then
  raise exception using errcode='40001',message='review acknowledgement cannot move backward or repeat a version';end if;
 seq:=coalesce(prior.receipt_sequence,0)+1;recorded:=clock_timestamp();
 result:=jsonb_build_object('contract_version','mip_hypothesis_review_receipt_v1','investigation_id',p_investigation,
  'request_id',p_request,'revision_id',p_revision,'revision',target_revision,'previous_receipt_id',p_previous,
  'receipt_sequence',seq::text,'recorded_at',to_char(recorded at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
  'review_scope','version_acknowledgement_only','is_approval',false,'resolves_reassessment',false,'publication_allowed',false);
 insert into mip_hypothesis.review_acknowledgements(investigation_id,request_id,reviewer_id,revision_id,revision,
  receipt_sequence,previous_receipt_id,receipt,recorded_at)
 values(p_investigation,p_request,p_user,p_revision,target_revision,seq,p_previous,result,recorded);
 return result;
end $$;

create function mip_hypothesis.review_history(p_user uuid,p_investigation uuid)
 returns jsonb language plpgsql security definer set search_path='' as $$
declare history jsonb; entries jsonb; latest uuid;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception using errcode='25001',message='hypothesis requires read committed';end if;
 perform 1 from mip_cutover_authority.publication_fence where id for share;
 if not found then raise exception using errcode='55000',message='hypothesis fence unavailable';end if;
 history:=mip_hypothesis.read_bound_history(p_user,p_investigation);
 select coalesce(jsonb_agg(jsonb_build_object('receipt',r.receipt,'target_status',
  case when exists(select 1 from jsonb_array_elements(history->'entries') e
   where e->>'revision_id'=r.revision_id::text and e->>'status'='available') then 'available' else 'withheld' end)
  order by r.receipt_sequence),'[]'::jsonb) into entries
 from mip_hypothesis.review_acknowledgements r where r.investigation_id=p_investigation and r.reviewer_id=p_user;
 select request_id into latest from mip_hypothesis.review_acknowledgements
  where investigation_id=p_investigation and reviewer_id=p_user order by receipt_sequence desc limit 1;
 return jsonb_build_object('contract_version','mip_hypothesis_review_history_v1','investigation_id',p_investigation,
  'entries',entries,'latest_receipt_id',latest,'current_user_only',true,'is_approval',false,
  'resolves_reassessment',false,'publication_allowed',false);
end $$;
revoke all on mip_hypothesis.review_acknowledgements from public,mip_hypothesis_gateway;
revoke all on function mip_hypothesis.acknowledge_review(uuid,uuid,uuid,uuid,uuid),mip_hypothesis.review_history(uuid,uuid) from public;
grant execute on function mip_hypothesis.acknowledge_review(uuid,uuid,uuid,uuid,uuid),mip_hypothesis.review_history(uuid,uuid) to mip_hypothesis_gateway;
reset role;

